import numpy as np
import pandas as pd

# smile(clean, T, S, r, q) is loaded: strike, m, iv for one expiry.

def atm_term_structure(clean, S, r, q):
    """At-the-money vol per expiry: the smile interpolated at m = 0."""
    out = {}
    for T in sorted(clean["T"].unique()):
        sm = smile(clean, T, S, r, q)
        sm = sm.dropna(subset=["iv"]).sort_values("m")   # np.interp needs rising x
        if len(sm) == 0:
            out[float(T)] = float("nan")
        else:
            out[float(T)] = float(np.interp(0.0, sm["m"], sm["iv"]))
    return pd.Series(out, name="atm_iv")

