widget.solution:
from math import sqrt

def forward_vol(s1, T1, s2, T2):
    """Vol between T1 and T2 implied by vols s1 to T1 and s2 to T2."""
    if not T2 > T1:
        raise ValueError("T2 must be later than T1")
    fwd_var = (s2 * s2 * T2 - s1 * s1 * T1) / (T2 - T1)   # variances add
    if fwd_var < 0:
        raise ValueError("total variance falls: calendar arbitrage")
    return sqrt(fwd_var)
